import json
ROBOTS = {"amr-1": {"battery": 18, "pos": "A동"}, "amr-2": {"battery": 76, "pos": "B동"}}

def get_status(robot):
    return ROBOTS[robot]

def send_mission(robot, dest):
    if ROBOTS[robot]["battery"] < 20:
        return {"ok": False, "reason": "배터리 부족"}
    return {"ok": True, "eta_min": 4}

TOOLS = {"get_status": get_status, "send_mission": send_mission}
SCRIPT = [  # 실제로는 LLM 출력
    {"thought": "amr-1 상태부터 본다", "action": "get_status", "args": {"robot": "amr-1"}},
    {"thought": "배터리 18% — 다른 로봇을 본다", "action": "get_status", "args": {"robot": "amr-2"}},
    {"thought": "amr-2 에 보낸다", "action": "send_mission", "args": {"robot": "amr-2", "dest": "C동"}},
    {"final": "amr-2 가 C동으로 출발(4분)"},
]
for step, out in enumerate(SCRIPT, 1):
    if "final" in out:
        print(f"[{step}] 답: {out['final']}")
        break
    obs = TOOLS[out["action"]](**out["args"])
    print(f"[{step}] 생각: {out['thought']} → {out['action']}{tuple(out['args'].values())} → {json.dumps(obs, ensure_ascii=False)}")

# [1] 생각: amr-1 상태부터 본다 → get_status('amr-1',) → {"battery": 18, "pos": "A동"}
# [2] 생각: 배터리 18% — 다른 로봇을 본다 → get_status('amr-2',) → {"battery": 76, "pos": "B동"}
# [3] 생각: amr-2 에 보낸다 → send_mission('amr-2', 'C동') → {"ok": true, "eta_min": 4}
# [4] 답: amr-2 가 C동으로 출발(4분)
